    Hypothesis CONT : forall (fx' : FPState) A' R' M' model',
        ainv MI A' M' model' -> mstd model' -> m_fs model' = m_fs model0 -> m_fds model' = m_fds model0 ->
        @fp_csr fx' = @fp_csr fx -> base_ok R' -> frame M' ->
        defined M' (sp - 32 - DEL_STACK) (32 + DEL_STACK) -> (forall a, zwin (sp - 32 - DEL_STACK) sp a -> ~ owned MI A' a) ->
        umapx MI NS nval A' M' obj1 bl2 bc2 ents2 ->
        umapx MI NS nval A' M' obj2 0 0 [] ->
        lapply (live MI A0) (free_ops bl1 bc1 ents1) (live MI A') ->
        eff MI A0 A' M0 M' W FOOT ->
        srealizes SEGS (cfg fx' R' END_PC M' model') K.

