      umapx MI 32 (nval32 SEGS) A0 M0 (st1 + 88) bl1 bc1 ents1 -> umapx MI 32 (nval32 SEGS) A0 M0 (st2 + 88) bl2 bc2 ents2 ->
      above_sp MI A0 sp (st1 + 88) 40 -> above_sp MI A0 sp (st2 + 88) 40 -> apart (st1 + 88) 40 (st2 + 88) 40 ->
      (forall b, In b (map fst (umap_blocks 32 bl1 bc1 ents1)) -> ~ In b (map fst (umap_blocks 32 bl2 bc2 ents2))) ->
      frame sp wra w8 w9 w18 M0 ->
      (forall (fx' : FPState) A' R' M' model',
        ainv MI A' M' model' -> mstd model' -> m_fs model' = m_fs model0 -> m_fds model' = m_fds model0 ->
        @fp_csr fx' = @fp_csr fx -> base_ok L R0 sp st1 st2 R' -> frame sp wra w8 w9 w18 M' ->
        defined M' (sp - 32 - DEL_STACK) (32 + DEL_STACK) -> (forall a, zwin (sp - 32 - DEL_STACK) sp a -> ~ owned MI A' a) ->
        umapx MI 32 (nval32 SEGS) A' M' (st1 + 88) bl2 bc2 ents2 ->
        umapx MI 32 (nval32 SEGS) A' M' (st2 + 88) 0 0 [] ->
        lapply (live MI A0) (free_ops bl1 bc1 ents1) (live MI A') ->
        eff MI A0 A' M0 M' (sp - (32 + DEL_STACK), sp) (fun a => umap_foot 32 (st1 + 88) bl1 bc1 ents1 a \/ umap_foot 32 (st2 + 88) bl2 bc2 ents2 a) ->
        srealizes SEGS (mkCfg (@mkst fx' R' (Z_to_bv 64 END_PC) M' (seg_rom SEGS)) model') K) ->
      srealizes SEGS (mkCfg (@mkst fx R0 (Z_to_bv 64 N_ENTRY) M0 (seg_rom SEGS)) model0) K.
End Stmt.

Section Spec.
Context {AC : AllocCeiling}.
  Variable L : Layout.
  Variable MI : MallocIface SEGS L.
  Variable ST : StaticsIface SEGS L.
  Variable DEL_STACK : Z.
  Hypothesis DEL_STACK_nn : 0 <= DEL_STACK.
  Hypothesis DEL : delete_rule_stmt SEGS L MI DEL_STACK.
  Hypothesis HLdel : ly_delete L = DELETE.
  Hypothesis HLimg_lo : forall a, in_ranges (ly_img L) a -> a < alloc_ceiling.
  Hypothesis HLrw_img : forall a, in_ranges (ly_rw L) a -> in_ranges (ly_img L) a.
  Hypothesis HLrelro_img : forall a, in_ranges (ly_relro L) a -> in_ranges (ly_img L) a.
  Hypothesis HLrw_relro : forall a, in_ranges (ly_rw L) a -> ~ in_ranges (ly_relro L) a.
  Hypothesis HLerr_rw : forall a, errno_win L a -> in_ranges (ly_rw L) a.

  Theorem nt_inl_spec : nt_inl_stmt L MI DEL_STACK.
Proof using AC L MI DEL_STACK DEL_STACK_nn DEL HLdel HLimg_lo HLrw_img HLerr_rw.
